local splitter = meldritch.subpatch("splitter")
local a = splitter:module("a", "gain", { gain = 0.5 })
local b = splitter:module("b", "gain", { gain = 0.25 })
local mix = splitter:module("mix", "mix")
splitter:connect(a.out, mix.left)
splitter:connect(b.out, mix.right)
splitter:input("signal", a.input, b.input)
splitter:output("audio", mix.out)

local graph = meldritch.graph()
local high = graph:module("high", "constant", { value = 0.4 })
local low = graph:module("low", "constant", { value = 0.2 })
local fallback = graph:module("fallback", "constant", { value = 0.1 })
local left = graph:instance("left", splitter)
local right = graph:instance("right", splitter)
local mix = graph:module("mix", "mix")
local output = graph:module("output", "output")
graph:connect(high.out, left.signal)
graph:connect(low.out, right.signal)
graph:normalize(fallback.out, right.signal)
graph:connect(left.audio, mix.left)
graph:connect(right.audio, mix.right)
graph:connect(mix.out, output.input)
return graph
